assert len(items) == 64, len(items)
roles = {}
for it in items:
    roles[it["role"]] = roles.get(it["role"], 0) + 1

prompts = Path(W + "/w1/prompts")
prompts.mkdir(parents=True, exist_ok=True)
for it in items:
    (prompts / f"{it['name']}.md").write_text(
        f"# {it['name']} — {it['role']} seat, mado round 36 wave 1\n\n"
        f"Lane: {LANE}\nRole: {it['role']}\n\n{it['prompt']}\n")
    it["prompt"] = (
        f"/skill:godspeed\n\nRead your assignment at {prompts}/{it['name']}.md and execute it "
        f"exactly. It carries your deliverable; this task's shared context carries the lane bounds, "
        f"the freeze and the write scope. 63 other seats run beside you read-only: write only your "
        f"own report and your own scratch directory, never a production file."
    )

spec = {
    "wave": "mado-r36-w1",
    "reportDir": ".ufo/waves/round-36/w1/reports",
    "context": CONTEXT,
    "items": items,
}
Path(W + "/w1-spec.json").write_text(json.dumps(spec, indent=1) + "\n")
